package com.ml.tblandroidtxt;
import org.json.JSONArray;import org.json.JSONObject;import java.util.List;
/** L3 runner with a hard persisted checkpoint between independent comparison and report review. */
public final class EditorialL3Runner {
 public interface Client{OpenAICompatibleClient.ChatResult complete(AppSettings s,PromptPair p,String id)throws Exception;}public static final class Result{public final long runId;public final String output;Result(long id,String out){runId=id;output=out;}}
 private final EditorialRepository repo;private final Client client;public EditorialL3Runner(EditorialRepository r){this(r,(s,p,id)->OpenAICompatibleClient.chatWithUsage(s,p,s.maxOutputTokens,id));}EditorialL3Runner(EditorialRepository r,Client c){repo=r;client=c;}
 public Result run(long chapterId,AppSettings settings)throws Exception{EditorialRepository.Chapter chapter=repo.getChapter(chapterId);if(chapter==null||chapter.state!=EditorialWorkflowV5.ChapterState.L2_CLOSED)throw new IllegalStateException("L3 requires a closed L2 machine gate");List<EditorialRepository.AssetSnapshot> assets=repo.chapterAssets(chapterId);String raw=find(assets,EditorialWorkflowV5.AssetRole.RAW).content,g=find(assets,EditorialWorkflowV5.AssetRole.GLOSSARY).content,p=find(assets,EditorialWorkflowV5.AssetRole.PRONOUN).content,vi=repo.latestEvidenceForChapter(chapterId,"VI_L2_TEXT"),viJson=repo.latestEvidenceForChapter(chapterId,"VI_L2_JSON"),report=repo.latestEvidenceForChapter(chapterId,"REPORT_L1_JSON");if(EditorialEvidenceValidator.validateL2Output(viJson)!=null||vi.trim().isEmpty())throw new IllegalStateException("L3 blocked by invalid VI_L2");if(EditorialEvidenceValidator.validateL1Report(report)!=null)throw new IllegalStateException("L3 blocked by invalid REPORT_L1");PromptPair first=EditorialL3ContextBuilder.independent(chapterId,raw,vi,g,p);long latestL2=repo.latestRunId(chapterId,"L2");boolean l2HasSceneCheckpoints=latestL2>0&&!repo.evidencePayload(latestL2,"L2_EDIT_SCENE_scene-001").isEmpty();if(l2HasSceneCheckpoints||!safe(first)||raw.length()+vi.length()+report.length()+g.length()+p.length()>EditorialL1ContextBuilder.MAX_INLINE_SOURCE_CHARS)return runSegmented(chapterId,settings,assets,report,false,-1);String manifest=new JSONObject().put("chapterId",String.valueOf(chapterId)).put("rawHash",HashUtil.sha256(raw)).put("viL2Hash",HashUtil.sha256(vi)).put("reportL1Hash",HashUtil.sha256(report)).put("reportHiddenInIndependent",true).toString();long runId=repo.createRun(chapterId,"L3",settings.provider,settings.model,HashUtil.sha256(first.system+"\n"+first.user),HashUtil.sha256(EditorialEvidenceSchema.VERSION),manifest);repo.saveEvidence(runId,"L3_CONTEXT_MANIFEST",manifest);repo.updateRunState(runId,"INDEPENDENT_RUNNING");repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L2_CLOSED,EditorialWorkflowV5.ChapterState.L3_READY);repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L3_READY,EditorialWorkflowV5.ChapterState.L3_INDEPENDENT_RUNNING);EditorialWorkflowV5.ChapterState active=EditorialWorkflowV5.ChapterState.L3_INDEPENDENT_RUNNING;
  try{OpenAICompatibleClient.ChatResult independent=client.complete(settings,first,"editorial-l3:"+runId+":independent");String error=EditorialL3IndependentContract.validate(independent.content,String.valueOf(chapterId));if(error!=null)throw new IllegalArgumentException("L3 independent contract failed: "+error);repo.saveEvidence(runId,"L3_INDEPENDENT_LEDGER",independent.content);repo.saveEvidence(runId,"L3_INDEPENDENT_USAGE",usage(independent));persistIndependentScenes(runId,new JSONObject(independent.content));repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L3_INDEPENDENT_RUNNING,EditorialWorkflowV5.ChapterState.L3_REPORT_REVIEW);active=EditorialWorkflowV5.ChapterState.L3_REPORT_REVIEW;repo.updateRunState(runId,"REPORT_REVIEW");PromptPair second=EditorialL3ContextBuilder.reportReview(chapterId,raw,vi,g,p,independent.content,report);requireSafe(second,"report review");repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L3_REPORT_REVIEW,EditorialWorkflowV5.ChapterState.L3_RUNNING);active=EditorialWorkflowV5.ChapterState.L3_RUNNING;repo.updateRunState(runId,"RUNNING");OpenAICompatibleClient.ChatResult finalResult=client.complete(settings,second,"editorial-l3:"+runId+":final");error=EditorialEvidenceValidator.validateL3Output(finalResult.content);if(error!=null)throw new IllegalArgumentException("L3 output contract failed: "+error);JSONObject root=new JSONObject(finalResult.content);if(!String.valueOf(chapterId).equals(root.optString("chapterId")))throw new IllegalArgumentException("L3 output chapterId mismatch");persistGates(runId,root.getJSONObject("gates"));repo.saveEvidence(runId,"CHANGE_SET",root.getJSONArray("changeSet").toString());repo.saveEvidence(runId,"FINAL_QA_JSON",finalResult.content);repo.saveEvidence(runId,"FINAL_QA_TEXT",root.getString("output"));repo.saveEvidence(runId,"L3_FINAL_USAGE",usage(finalResult));repo.updateRunState(runId,"CLOSED");repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L3_RUNNING,EditorialWorkflowV5.ChapterState.RELEASE_READY);return new Result(runId,root.getString("output"));}
  catch(Exception e){repo.saveEvidence(runId,"L3_FAILURE",new JSONObject().put("phase",active.name()).put("message",String.valueOf(e.getMessage())).toString());repo.updateRunState(runId,"FAILED");repo.transitionChapter(chapterId,active,EditorialWorkflowV5.ChapterState.FAILED);throw e;}}
 public Result retry(long chapterId,AppSettings settings)throws Exception{EditorialRepository.Chapter c=repo.getChapter(chapterId);if(c==null||c.state!=EditorialWorkflowV5.ChapterState.FAILED)throw new IllegalStateException("No failed L3 checkpoint to retry");long runId=repo.latestRunId(chapterId,"L3");if(runId<=0)throw new IllegalStateException("Failed L3 run not found");List<EditorialRepository.AssetSnapshot> assets=repo.chapterAssets(chapterId);String report=repo.latestEvidenceForChapter(chapterId,"REPORT_L1_JSON");repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.FAILED,EditorialWorkflowV5.ChapterState.L3_READY);repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L3_READY,EditorialWorkflowV5.ChapterState.L3_INDEPENDENT_RUNNING);repo.updateRunState(runId,"INDEPENDENT_RUNNING");return runSegmented(chapterId,settings,assets,report,true,runId);}
 private Result runSegmented(long chapterId,AppSettings settings,List<EditorialRepository.AssetSnapshot> assets,String report,boolean reuse,long existingRun)throws Exception{EditorialSceneSegmenter.Plan plan=EditorialL1ContextBuilder.segmentRawForL1(assets);EditorialRepository.AssetSnapshot g=find(assets,EditorialWorkflowV5.AssetRole.GLOSSARY),p=find(assets,EditorialWorkflowV5.AssetRole.PRONOUN);long l2Run=repo.latestRunId(chapterId,"L2");if(l2Run<=0)throw new IllegalStateException("Segmented L3 requires L2 checkpoints");String manifest=new JSONObject().put("chapterId",String.valueOf(chapterId)).put("mode","SEGMENTED").put("rawHash",plan.map.sha256).put("reportL1Hash",HashUtil.sha256(report)).put("reportHiddenInIndependent",true).toString();long runId=existingRun>0?existingRun:repo.createRun(chapterId,"L3",settings.provider,settings.model,HashUtil.sha256(EditorialL3SceneContract.schema()),HashUtil.sha256(EditorialEvidenceSchema.VERSION),manifest);if(!reuse){repo.saveEvidence(runId,"L3_CONTEXT_MANIFEST",manifest);repo.updateRunState(runId,"INDEPENDENT_RUNNING");repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L2_CLOSED,EditorialWorkflowV5.ChapterState.L3_READY);repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L3_READY,EditorialWorkflowV5.ChapterState.L3_INDEPENDENT_RUNNING);}EditorialWorkflowV5.ChapterState active=EditorialWorkflowV5.ChapterState.L3_INDEPENDENT_RUNNING;String activeScene="independent";
  try{JSONArray independentScenes=new JSONArray(),issues=new JSONArray();java.util.ArrayList<String> viScenes=new java.util.ArrayList<>();for(EditorialSceneSegmenter.Scene scene:plan.scenes){String l2Payload=repo.evidencePayload(l2Run,"L2_EDIT_SCENE_"+scene.id);if(EditorialL2SceneContract.validate(l2Payload)!=null)throw new IllegalStateException("Missing closed VI_L2 checkpoint for "+scene.id);JSONObject l2=new JSONObject(l2Payload);if(!scene.startAnchor.equals(l2.optString("rawStart"))||!scene.endAnchor.equals(l2.optString("rawEnd")))throw new IllegalStateException("VI_L2 checkpoint anchors mismatch at "+scene.id);String viScene=l2.getString("output");viScenes.add(viScene);activeScene="independent:"+scene.id;String type="L3_INDEPENDENT_SCENE_"+scene.id,payload=reuse?repo.evidencePayload(runId,type):"";OpenAICompatibleClient.ChatResult response=null;if(EditorialL3IndependentContract.validate(payload,String.valueOf(chapterId))!=null){PromptPair prompt=EditorialL3ContextBuilder.independentScene(chapterId,scene,viScene,g.content,p.content);requireSafe(prompt,"independent scene");response=client.complete(settings,prompt,"editorial-l3:"+runId+":independent:"+scene.id);payload=response.content;}JSONObject root=new JSONObject(payload);String error=EditorialL3IndependentContract.validate(payload,String.valueOf(chapterId));if(error!=null)throw new IllegalArgumentException("L3 independent scene contract failed: "+error);JSONArray rows=root.getJSONArray("scenes");if(rows.length()!=1)throw new IllegalArgumentException("Independent checkpoint must contain one scene");JSONObject row=rows.getJSONObject(0);if(!scene.id.equals(row.optString("id"))||!scene.startAnchor.equals(row.optString("rawStart"))||!scene.endAnchor.equals(row.optString("rawEnd")))throw new IllegalArgumentException("Independent anchors mismatch at "+scene.id);independentScenes.put(row);JSONArray local=root.getJSONArray("issues");for(int x=0;x<local.length();x++)issues.put(local.getJSONObject(x));repo.saveScene(runId,"l3-independent-"+scene.id,scene.startAnchor,scene.endAnchor,"CLOSED",row.toString());if(response!=null){repo.saveEvidence(runId,type,payload);repo.saveEvidence(runId,type+"_USAGE",usage(response));}}
   JSONObject independentDraft=new JSONObject().put("chapterId",String.valueOf(chapterId)).put("scenes",independentScenes).put("issues",issues);activeScene="voice-audit";String voicePayload=reuse?repo.evidencePayload(runId,"L3_CROSS_SCENE_VOICE_AUDIT"):"";OpenAICompatibleClient.ChatResult voiceResponse=null;if(EditorialL3VoiceAuditContract.validate(voicePayload,String.valueOf(chapterId))!=null){PromptPair voicePrompt=EditorialL3ContextBuilder.voiceAudit(chapterId,independentDraft.toString(),p.content);requireSafe(voicePrompt,"voice audit");voiceResponse=client.complete(settings,voicePrompt,"editorial-l3:"+runId+":voice-audit");voicePayload=voiceResponse.content;}String voiceError=EditorialL3VoiceAuditContract.validate(voicePayload,String.valueOf(chapterId));if(voiceError!=null)throw new IllegalArgumentException(voiceError);if(voiceResponse!=null){repo.saveEvidence(runId,"L3_CROSS_SCENE_VOICE_AUDIT",voicePayload);repo.saveEvidence(runId,"L3_CROSS_SCENE_VOICE_USAGE",usage(voiceResponse));}JSONObject independent=independentDraft.put("voiceAudit",new JSONObject(voicePayload)).put("crossSceneVoiceAudit","CLOSED").put("status","CLOSED");String independentError=EditorialL3IndependentContract.validate(independent.toString(),String.valueOf(chapterId));if(independentError!=null)throw new IllegalStateException(independentError);repo.saveEvidence(runId,"L3_INDEPENDENT_LEDGER",independent.toString());repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L3_INDEPENDENT_RUNNING,EditorialWorkflowV5.ChapterState.L3_REPORT_REVIEW);active=EditorialWorkflowV5.ChapterState.L3_REPORT_REVIEW;repo.updateRunState(runId,"REPORT_REVIEW");repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L3_REPORT_REVIEW,EditorialWorkflowV5.ChapterState.L3_RUNNING);active=EditorialWorkflowV5.ChapterState.L3_RUNNING;repo.updateRunState(runId,"RUNNING");StringBuilder output=new StringBuilder();JSONArray changeSet=new JSONArray();for(int i=0;i<plan.scenes.size();i++){EditorialSceneSegmenter.Scene scene=plan.scenes.get(i);activeScene="final:"+scene.id;String type="L3_FINAL_SCENE_"+scene.id,payload=reuse?repo.evidencePayload(runId,type):"";OpenAICompatibleClient.ChatResult response=null;if(EditorialL3SceneContract.validate(payload)!=null){PromptPair prompt=EditorialL3ContextBuilder.finalScene(chapterId,scene,viScenes.get(i),g.content,p.content,new JSONObject().put("chapterId",String.valueOf(chapterId)).put("scenes",new JSONArray().put(independentScenes.getJSONObject(i))).put("issues",issuesForScene(issues,scene)).put("crossSceneVoiceAudit","CLOSED").put("status","CLOSED").toString(),reportForScene(report,scene));requireSafe(prompt,"final scene");response=client.complete(settings,prompt,"editorial-l3:"+runId+":final:"+scene.id);payload=response.content;}JSONObject row=new JSONObject(payload);String error=EditorialL3SceneContract.validate(payload);if(error!=null)throw new IllegalArgumentException("L3 final scene contract failed: "+error);if(!scene.id.equals(row.optString("sceneId"))||!scene.startAnchor.equals(row.optString("rawStart"))||!scene.endAnchor.equals(row.optString("rawEnd")))throw new IllegalArgumentException("Final anchors mismatch at "+scene.id);output.append(row.getString("output"));JSONArray local=row.getJSONArray("changeSet");for(int x=0;x<local.length();x++)changeSet.put(local.getJSONObject(x));repo.saveScene(runId,"l3-final-"+scene.id,scene.startAnchor,scene.endAnchor,"CLOSED",row.toString());if(response!=null){repo.saveEvidence(runId,type,payload);repo.saveEvidence(runId,type+"_USAGE",usage(response));}}
   JSONObject gates=closedGates(),root=new JSONObject().put("schema",EditorialEvidenceSchema.VERSION).put("run","L3").put("chapterId",String.valueOf(chapterId)).put("output",output.toString()).put("outputComplete",true).put("changeSet",changeSet).put("crossSceneVoiceAudit","CLOSED").put("finalReadThrough","CLOSED").put("gates",gates);String error=EditorialEvidenceValidator.validateL3Output(root.toString());if(error!=null)throw new IllegalStateException("Aggregated L3 contract failed: "+error);persistGates(runId,gates);repo.saveEvidence(runId,"CHANGE_SET",changeSet.toString());repo.saveEvidence(runId,"FINAL_QA_JSON",root.toString());repo.saveEvidence(runId,"FINAL_QA_TEXT",output.toString());repo.updateRunState(runId,"CLOSED");repo.transitionChapter(chapterId,EditorialWorkflowV5.ChapterState.L3_RUNNING,EditorialWorkflowV5.ChapterState.RELEASE_READY);return new Result(runId,output.toString());
  }catch(Exception e){repo.saveEvidence(runId,"L3_FAILURE",new JSONObject().put("phase",active.name()).put("scene",activeScene).put("message",String.valueOf(e.getMessage())).toString());repo.updateRunState(runId,"FAILED");repo.transitionChapter(chapterId,active,EditorialWorkflowV5.ChapterState.FAILED);throw e;}}
 private void persistIndependentScenes(long id,JSONObject root)throws Exception{JSONArray a=root.getJSONArray("scenes");for(int i=0;i<a.length();i++){JSONObject s=a.getJSONObject(i);repo.saveScene(id,"l3-independent-"+s.getString("id"),s.getString("rawStart"),s.getString("rawEnd"),"CLOSED",s.toString());}}private void persistGates(long id,JSONObject g){save(id,EditorialWorkflowV5.Gate.COVERAGE,g,"coverage");save(id,EditorialWorkflowV5.Gate.FIDELITY,g,"fidelity");save(id,EditorialWorkflowV5.Gate.REFERENCE_VOICE,g,"referenceVoice");save(id,EditorialWorkflowV5.Gate.CONTINUITY_STRUCTURE,g,"continuityStructure");save(id,EditorialWorkflowV5.Gate.CHANGE,g,"change");}private void save(long id,EditorialWorkflowV5.Gate gate,JSONObject g,String k){repo.saveGate(id,gate,EditorialWorkflowV5.GateStatus.valueOf(g.optString(k)),g.toString());}
 private static JSONArray issuesForScene(JSONArray issues,EditorialSceneSegmenter.Scene scene)throws Exception{JSONArray out=new JSONArray();for(int i=0;i<issues.length();i++){JSONObject x=issues.getJSONObject(i);String a=x.optString("rawAnchor");if(a.compareTo(scene.startAnchor)>=0&&a.compareTo(scene.endAnchor)<=0)out.put(x);}return out;}private static String reportForScene(String report,EditorialSceneSegmenter.Scene scene)throws Exception{JSONObject r=new JSONObject(report),out=new JSONObject().put("chapterId",r.optString("chapterId"));JSONArray scenes=new JSONArray();for(int i=0;i<r.getJSONArray("scenes").length();i++){JSONObject x=r.getJSONArray("scenes").getJSONObject(i);if(scene.id.equals(x.optString("id")))scenes.put(x);}JSONArray issues=new JSONArray();for(int i=0;i<r.getJSONArray("issues").length();i++){JSONObject x=r.getJSONArray("issues").getJSONObject(i);String a=x.optString("rawAnchor");if(a.compareTo(scene.startAnchor)>=0&&a.compareTo(scene.endAnchor)<=0)issues.put(x);}return out.put("scenes",scenes).put("issues",issues).toString();}private static JSONObject closedGates()throws Exception{return new JSONObject().put("coverage","CLOSED").put("fidelity","CLOSED").put("referenceVoice","CLOSED").put("continuityStructure","CLOSED").put("change","CLOSED");}
 private static boolean safe(PromptPair x){return x.system.length()+x.user.length()<=EditorialL1ContextBuilder.MAX_INLINE_SOURCE_CHARS;}private static void requireSafe(PromptPair x,String phase){if(!safe(x))throw new IllegalStateException("L3 "+phase+" exceeds safe context; smaller segmentation is required");}private static EditorialRepository.AssetSnapshot find(List<EditorialRepository.AssetSnapshot>a,EditorialWorkflowV5.AssetRole role){for(EditorialRepository.AssetSnapshot x:a)if(x.role==role)return x;throw new IllegalArgumentException("Missing "+role);}private static String usage(OpenAICompatibleClient.ChatResult r)throws Exception{return new JSONObject().put("promptTokens",r.promptTokens).put("completionTokens",r.completionTokens).put("totalTokens",r.totalTokens).put("finishReason",r.finishReason).put("responseId",r.providerResponseId).toString();}
}
